insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$leopoldina$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/8EFCBF0A (Dec. 3.707/2014) ; https://www.diariomunicipal.com.br/amm-mg/materia/4FFBE65A (Dec. 5.474/2025, Carnaval)$q$, $q$Atos oficiais de Leopoldina: domínio público (Lei 9.610/1998, art. 8º, IV). Geometria da Av. Jenu Pinto de Faria: OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap). Limite municipal (registro da ponte): IBGE, Malha Municipal (dados públicos).$q$, 5, $q$Dec. 3.707/2014: ponte de concreto da estrada velha de Cataguases proibida a veículos pesados acima de 12 t. A ponte é descrita só em texto (perto da propriedade do Sr. Alcir Queiros e de uma antiga escola municipal) e não foi localizada no OSM: regra desativada por falta de geometria confiável (pendência). Carnaval (Av. Jehu/Jenu Pinto de Faria): restrição de evento, desativada.$q$);
